package net.civeira.phylax.features.oauth.tokensecurity.domain.gateway;

import java.time.Instant;

/**
 * Domain port for JWT revocation storage.
 *
 * <p>
 * Allows individual JWTs to be revoked by JTI before they expire (logout, security events). The
 * store is tenant-scoped and must be cleaned up periodically.
 * </p>
 */
public interface TokenRevocationGateway {

  /**
   * Marks a JWT as revoked until its natural expiry.
   *
   * @param jti JWT ID claim
   * @param tenantId tenant identifier
   * @param tokenType token type (e.g. {@code access_token}, {@code refresh_token})
   * @param expiresAt token expiry — used to schedule cleanup
   */
  void revokeJti(String jti, String tenantId, String tokenType, Instant expiresAt);

  /**
   * Returns {@code true} if the JTI has been revoked.
   *
   * @param jti JWT ID claim
   * @param tenantId tenant identifier
   * @return true when the token is revoked
   */
  boolean isRevoked(String jti, String tenantId);

  /**
   * Consumes a JWT ID once: only the first caller gets {@code true}.
   *
   * Used to rotate refresh tokens; a second consumption of the same JTI is a reuse.
   *
   * @param jti JWT ID claim
   * @param tenantId tenant identifier
   * @param tokenType token type
   * @param expiresAt token expiry — used to schedule cleanup
   * @return true only when this call consumed the JTI
   */
  boolean consumeJti(String jti, String tenantId, String tokenType, Instant expiresAt);

  /**
   * Removes expired revocation entries.
   *
   * <p>
   * Called periodically by maintenance jobs. Entries whose associated token has already expired are
   * safe to delete.
   * </p>
   */
  void cleanup();

  /**
   * Revokes the access and refresh tokens of the user's interactive sessions with a client.
   *
   * <p>
   * Called on theft detection: when a refresh token JTI appears that was already revoked, the
   * tokens registered on the user's sessions for the same client and tenant are invalidated to
   * limit blast radius. Tokens of grants without session are covered by the revocation of their
   * family; tokens of the same user name in other tenants are never touched.
   * </p>
   *
   * @param username authenticated username
   * @param clientId OAuth client identifier
   * @param tenantId tenant identifier
   */
  void revokeAllForUser(String username, String clientId, String tenantId);

  /**
   * Revokes all non-expired access and refresh tokens issued for a given session.
   *
   * <p>
   * Called when a session is explicitly revoked (e.g. from the active-sessions management API).
   * Bulk-inserts matching JTIs from {@code _oauth_session_token} into {@code _oauth_revoked_jti}.
   * </p>
   *
   * @param sessionId session identifier
   * @param tenantId tenant identifier
   */
  void revokeAllForSession(String sessionId, String tenantId);
}
